<script lang="ts">
import {AdminPanel} from '@mutsuna/ui/admin-layout';
import {Button} from '@mutsuna/ui/button';
import {Input} from '@mutsuna/ui/input';
import {Checkbox} from '@mutsuna/ui/checkbox';
import * as Dialog from '@mutsuna/ui/responsive-dialog';
import {showErrorToast,showSuccessToast} from '@mutsuna/ui/sonner';
import {Plus,Pencil,UsersRound,Unlink,Mail} from '@lucide/svelte';
import Picker from './Picker.svelte';
import type {State,Teacher} from '../lib/scheduler';
import {renameTeacherReferences} from '../lib/teacher-identity';
import {slackProfileImage} from '../lib/slack-profile-image';
import {onMount} from 'svelte';

let {roomAdmin=false,state:s,room,onChange}:{roomAdmin?:boolean;state:State;room:string;onChange:(s:State,text:string)=>void}=$props();
let roomFilter=$state('all'),roomsMode=$state('append'),curriculaMode=$state('append');
let newName=$state(''),edit=$state<Teacher|null>(null),originalName=$state('');
let bulkOpen=$state(false),selectedTeachers=$state<string[]>([]),bulkRooms=$state<string[]>([]),bulkCurricula=$state<string[]>([]),updateRooms=$state(true),updateCurricula=$state(true);
type SlackRequest={slack_user_id:string;email:string|null;display_name:string|null;requested_teacher_name:string};
type SlackLink={picture_url?:string|null;teacher_id?:string;slack_user_id:string;email:string|null;display_name:string|null;teacher_name:string};
let failedImages=$state<string[]>([]);
let slackRequests=$state<SlackRequest[]>([]);
let slackLinks=$state<SlackLink[]>([]);
let slackStatus=$state<'loading'|'ready'|'error'>('loading');
const curricula=$derived(s.settings?.curricula||[]),rooms=$derived(s.settings?.campuses||[]);
const sortedTeachers=$derived([...s.teachers].sort((a,b)=>teacherRank(a)-teacherRank(b)||a.name.localeCompare(b.name,'ja')));
const visibleTeachers=$derived(sortedTeachers.filter(teacher=>roomFilter==='all'||(roomFilter==='unassigned'?!teacher.rooms?.length:teacher.rooms?.includes(roomFilter))));
const filterRooms=$derived([...new Set([...rooms,...s.teachers.flatMap(teacher=>teacher.rooms||[])])]);
function teacherRank(teacher:Teacher){return teacher.rooms?.includes(room)?0:1}
function add(){const name=newName.trim();if(!name||s.teachers.some(x=>x.name===name)){showErrorToast('重複しない名前を入力してください');return}const next=structuredClone(s);next.teachers.push({id:crypto.randomUUID(),name,email:'',autoAttendance:false,autoAssignLessons:true,canSuperviseExam:false,max:3,curricula:[],rooms:[]});onChange(next,`${name}を追加`);newName=''}
function open(teacher:Teacher){originalName=teacher.name;edit=structuredClone({...teacher,curricula:teacher.curricula||[],rooms:teacher.rooms||[]})}
function toggle(field:'curricula'|'rooms'|'adminRooms',value:string,checked:boolean){if(!edit)return;edit[field]=checked?[...(edit[field]||[]),value]:(edit[field]||[]).filter(x=>x!==value)}
function save(){if(!edit)return;const teacher=$state.snapshot(edit),name=teacher.name.trim();if(!name){showErrorToast('名前を入力してください');return}if(s.teachers.some(x=>x.name===name&&x.name!==originalName)){showErrorToast('同じ名前が登録されています');return}if(roomAdmin){const next=structuredClone(s),target=next.teachers.find(item=>item.id===teacher.id);if(!target)return;target.rooms=[...new Set(teacher.rooms||[])];onChange(next,`${name}の担当教室を更新`);edit=null;return}teacher.name=name;teacher.email=teacher.email?.trim().toLowerCase()||'';if(teacher.email&&s.teachers.some(x=>x.name!==originalName&&x.email?.trim().toLowerCase()===teacher.email)){showErrorToast('同じメールアドレスが登録されています');return}teacher.max=Math.max(1,Math.min(3,Number(teacher.max)||3));teacher.curricula=[...new Set(teacher.curricula||[])];teacher.rooms=[...new Set(teacher.rooms||[])];const next=structuredClone(s),index=next.teachers.findIndex(x=>x.name===originalName);next.teachers[index]=teacher;renameTeacherReferences(next,originalName,name);onChange(next,`${originalName}のスタッフ情報を更新`);edit=null;showSuccessToast('スタッフ情報を反映しました。右上の「変更を保存」で確定してください')}
function toggleList(list:string[],value:string,checked:boolean){return checked?[...new Set([...list,value])]:list.filter(x=>x!==value)}
function openBulk(){selectedTeachers=[];bulkRooms=[];bulkCurricula=[];updateRooms=true;updateCurricula=!roomAdmin;roomsMode='append';curriculaMode='append';bulkOpen=true}
function applyBulk(){if(!selectedTeachers.length){showErrorToast('対象のスタッフを選択してください');return}if(!updateRooms&&!updateCurricula){showErrorToast('更新する項目を選択してください');return}const next=structuredClone(s);for(const teacher of next.teachers.filter(x=>selectedTeachers.includes(x.name))){if(updateRooms)teacher.rooms=[...new Set([...(roomsMode==='append'?teacher.rooms||[]:[]),...bulkRooms])];if(updateCurricula&&!roomAdmin)teacher.curricula=[...new Set([...(curriculaMode==='append'?teacher.curricula||[]:[]),...bulkCurricula])]}onChange(next,`${selectedTeachers.length}人の担当範囲を一括更新`);bulkOpen=false;showSuccessToast(`${selectedTeachers.length}人に一括設定しました。右上の「変更を保存」で確定してください`)}
async function loadSlackRequests(){slackStatus='loading';try{const response=await fetch('/api/slack-staff/approvals'),result=await response.json();if(!response.ok)throw Error();slackRequests=result.requests||[];slackLinks=(result.linked||[]).map((link:SlackLink)=>({...link,teacher_id:link.teacher_id||s.teachers.find(teacher=>teacher.name===link.teacher_name)?.id}));slackStatus='ready'}catch{slackStatus='error'}}
async function decideSlack(request:SlackRequest,action:'approve'|'reject'){const response=await fetch('/api/slack-staff/approvals',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({slackUserId:request.slack_user_id,teacherName:request.requested_teacher_name,action})}),result=await response.json();if(!response.ok){showErrorToast(result.error||'処理できませんでした');return}slackRequests=slackRequests.filter(item=>item.slack_user_id!==request.slack_user_id);showSuccessToast(action==='approve'?'Slackアカウントを承認しました':'申請を差し戻しました');if(action==='approve')setTimeout(()=>location.reload(),350)}
async function unlinkSlack(link:SlackLink){const response=await fetch('/api/slack-staff/approvals',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({slackUserId:link.slack_user_id,action:'unlink'})}),result=await response.json();if(!response.ok){showErrorToast(result.error||'紐付けを解除できませんでした');return}slackLinks=slackLinks.filter(item=>item.slack_user_id!==link.slack_user_id);showSuccessToast(`${link.teacher_name}のSlack紐付けを解除しました`)}
onMount(()=>{if(!roomAdmin)void loadSlackRequests()});
</script>

{#if slackRequests.length}<AdminPanel title="Slack認証の承認待ち"><div class="slack-requests">{#each slackRequests as request}<div><div><strong>{request.requested_teacher_name}</strong><span>{request.display_name||'Slack利用者'} · {request.email||'メールアドレスなし'}</span></div><Button size="sm" variant="outline" onclick={()=>decideSlack(request,'reject')}>差し戻す</Button><Button size="sm" onclick={()=>decideSlack(request,'approve')}>承認</Button></div>{/each}</div></AdminPanel>{/if}
<section aria-label="スタッフ一覧">
 <div class="teacher-toolbar">{#if !roomAdmin}<div class="teacher-add"><Input aria-label="追加するスタッフ名" bind:value={newName} placeholder="追加するスタッフ名"/><Button onclick={add}><Plus size={16}/>追加</Button></div>{/if}<div class="teacher-filter"><Picker label="担当教室で絞り込む" value={roomFilter} onchange={value=>roomFilter=value} items={[{value:'all',label:'すべての教室'},...filterRooms.map(item=>({value:item,label:item})),{value:'unassigned',label:'担当教室なし'}]}/><span>{visibleTeachers.length}人</span></div><Button variant="outline" onclick={openBulk}><UsersRound size={16}/>担当範囲を一括設定</Button></div>
 {#if !roomAdmin && slackStatus==='error'}<div class="slack-error" role="status">Slack連携の状態を取得できませんでした。<Button variant="ghost" size="sm" onclick={loadSlackRequests}>再読み込み</Button></div>{/if}

 <div class="teacher-list">
 {#each visibleTeachers as teacher}
 {@const links=slackLinks.filter(link=>link.teacher_id?link.teacher_id===teacher.id:link.teacher_name===teacher.name)}
 {@const picture=links.map(link=>slackProfileImage(link.picture_url)).find(url=>url&&!failedImages.includes(url))}
 <article class="teacher-row" aria-label={teacher.name}>
  <div class="teacher-identity"><span class="avatar" aria-hidden="true">{#if !roomAdmin && picture}<img src={picture} alt="" width="40" height="40" loading="lazy" referrerpolicy="no-referrer" onerror={()=>{failedImages=[...failedImages,picture]}}/>{:else}{teacher.name[0]}{/if}</span><div class="teacher-info"><div class="teacher-name"><strong>{teacher.name}</strong>{#if !roomAdmin && slackStatus==='ready' && links.length}<span class="slack-indicator" title="Slack連携済み"><span aria-hidden="true">↗</span></span>{/if}{#if teacher.email?.trim()}<span class="email-indicator" role="img" aria-label="メールアドレス登録済み" title="メールアドレス登録済み"><Mail size={18} aria-hidden="true"/></span>{/if}{#if teacher.adminRooms?.length}<span class="role-badge">管理者</span>{/if}</div><div class="teacher-rooms" aria-label="担当教室">{#each teacher.rooms||[] as item}<span class="detail-chip" class:current-room={item===room}>{item}</span>{:else}<span class="unassigned">担当教室なし</span>{/each}</div></div><Button variant="outline" size="sm" aria-label={`${teacher.name}の情報を編集`} onclick={()=>open(teacher)}><Pencil size={14}/>編集</Button></div>


 </article>
 {:else}<div class="teacher-empty"><UsersRound size={28}/><strong>{s.teachers.length?'該当するスタッフがいません':'スタッフが登録されていません'}</strong><p>{s.teachers.length?'教室の絞り込みを変更してください。':roomAdmin?'管理教室のスタッフが登録されると、ここに表示されます。':'上の入力欄からスタッフを追加してください。'}</p></div>{/each}
 </div>
</section>

<Dialog.Root bind:open={()=>!!edit,(open:boolean)=>{if(!open)edit=null}}><Dialog.Content><Dialog.Header><Dialog.Title>スタッフ情報を編集</Dialog.Title><Dialog.Description>{roomAdmin?'管理教室への担当追加・解除ができます。共通プロフィールはマスターが編集します。':'メールアドレスがSlackと一致すると、初回ログイン時に自動で紐付きます。'}</Dialog.Description></Dialog.Header>{#if edit}<Dialog.Body>{#if !roomAdmin}<div class="teacher-form"><label>名前<Input bind:value={edit.name}/></label><label>メールアドレス<Input type="email" bind:value={edit.email} placeholder="name@example.com"/></label><label>担当上限<Input type="number" min={1} max={3} bind:value={edit.max}/></label></div>{/if}<div class="curriculum-field"><strong>担当教室（複数選択）</strong><div class="curriculum-options">{#each rooms as item}<label><Checkbox checked={(edit.rooms||[]).includes(item)} onCheckedChange={value=>toggle('rooms',item,value===true)}/>{item}</label>{/each}</div></div>{#if !roomAdmin}<div class="curriculum-field"><strong>管理者権限を付与する教室（複数選択）</strong><p>本人のSlackログインで、選択した教室の授業・生徒・シフトを管理できます。チェックを外して保存すると解除されます。スタッフの共通プロフィール・権限・全体設定はマスターだけが変更できます。</p><div class="curriculum-options">{#each rooms as item}<label><Checkbox checked={(edit.adminRooms||[]).includes(item)} onCheckedChange={value=>toggle('adminRooms',item,value===true)}/>{item}</label>{/each}</div></div><div class="curriculum-field"><strong>出勤予定の扱い</strong><label class="bulk-enable"><Checkbox checked={edit.autoAttendance===true} onCheckedChange={value=>{if(edit)edit.autoAttendance=value===true}}/>シフト希望○を出勤予定にする</label><p class="bulk-note">担当教室の○を、授業や業務がなくても出勤予定に含めます。オフの場合は、授業・固定業務・採用済みの勤務から判定します。</p></div><div class="curriculum-field"><strong>授業の自動割り当て</strong><label class="bulk-enable"><Checkbox checked={edit.autoAssignLessons!==false} onCheckedChange={value=>{if(edit)edit.autoAssignLessons=value===true}}/>授業の自動割り当て対象</label><p class="bulk-note">オフの場合は授業を手動で割り当てます。既存の担当授業は「未担当を埋める」では保持します。「全体を組み直す」では担当を外し、自動割り当て対象の先生で再計算します。出勤予定の設定とは独立しています。</p></div><div class="curriculum-field"><strong>検定の担当</strong><label class="bulk-enable"><Checkbox checked={edit.canSuperviseExam===true} onCheckedChange={value=>{if(edit)edit.canSuperviseExam=value===true}}/>検定対応可</label><p class="bulk-note">担当教室・カリキュラムが合う検定本番を担当できます。管理者権限とは別の設定です。</p></div><div class="curriculum-field"><strong>教えられるカリキュラム</strong><div class="curriculum-options">{#each curricula as course}<label><Checkbox checked={(edit.curricula||[]).includes(course)} onCheckedChange={value=>toggle('curricula',course,value===true)}/>{course}</label>{:else}<p>設定ページでカリキュラムを登録してください。</p>{/each}</div></div>{/if}{#if !roomAdmin}<div class="teacher-slack"><strong class="slack-label">Slack連携</strong><p class="slack-unlink-note">連携の解除はすぐに反映されます。</p>{#if slackStatus==='loading'}<span class="unassigned">確認中…</span>{:else if slackStatus==='error'}<span class="unassigned">確認できません</span>{:else if slackLinks.some(link=>link.teacher_id?link.teacher_id===edit?.id:link.teacher_name===originalName)}{#each slackLinks.filter(link=>link.teacher_id?link.teacher_id===edit?.id:link.teacher_name===originalName) as link}<div class="slack-account"><span class="connected">連携済み</span><span class="slack-account-name">{link.display_name||'Slack利用者'}{#if link.email}<span class="slack-email">{link.email}</span>{/if}</span><Button size="sm" variant="ghost" aria-label={`${originalName}のSlack連携を解除`} onclick={()=>unlinkSlack(link)}><Unlink size={14}/>連携を解除</Button></div>{/each}{:else}<span class="unassigned">未連携</span>{/if}</div>{/if}</Dialog.Body><Dialog.Footer><Button variant="outline" onclick={()=>edit=null}>キャンセル</Button><Button onclick={save}>変更を反映</Button></Dialog.Footer>{/if}</Dialog.Content></Dialog.Root>

<Dialog.Root bind:open={bulkOpen}><Dialog.Content class="bulk-teacher-dialog"><Dialog.Header><Dialog.Title>担当範囲を一括設定</Dialog.Title><Dialog.Description>複数のスタッフへ、同じ担当教室とカリキュラムをまとめて設定します。</Dialog.Description></Dialog.Header><Dialog.Body><div class="bulk-section"><strong>対象のスタッフ</strong><div class="curriculum-options">{#each s.teachers as teacher}<label><Checkbox checked={selectedTeachers.includes(teacher.name)} onCheckedChange={value=>selectedTeachers=toggleList(selectedTeachers,teacher.name,value===true)}/>{teacher.name}</label>{/each}</div><div class="quick-actions"><Button variant="ghost" size="sm" onclick={()=>selectedTeachers=s.teachers.map(x=>x.name)}>全員を選択</Button><Button variant="ghost" size="sm" onclick={()=>selectedTeachers=[]}>選択解除</Button></div></div><div class="bulk-section"><label class="bulk-enable"><Checkbox bind:checked={updateRooms}/><strong>担当教室を更新</strong></label>{#if updateRooms}<Picker label="担当教室の更新方法" value={roomsMode} onchange={value=>roomsMode=value} items={[{value:'append',label:'追加（既存の担当を残す）'},{value:'replace',label:'上書き（選択した教室に置き換える）'}]}/><div class="curriculum-options">{#each rooms as item}<label><Checkbox checked={bulkRooms.includes(item)} onCheckedChange={value=>bulkRooms=toggleList(bulkRooms,item,value===true)}/>{item}</label>{/each}</div><p class="bulk-note">{roomsMode==='append'?'選択した教室を追加します。未選択なら変更しません。':'既存の担当教室を置き換えます。未選択なら担当教室をすべて解除します。'}</p>{/if}</div>{#if !roomAdmin}<div class="bulk-section"><label class="bulk-enable"><Checkbox bind:checked={updateCurricula}/><strong>カリキュラムを更新</strong></label>{#if updateCurricula}<Picker label="カリキュラムの更新方法" value={curriculaMode} onchange={value=>curriculaMode=value} items={[{value:'append',label:'追加（既存の担当を残す）'},{value:'replace',label:'上書き（選択した内容に置き換える）'}]}/><div class="curriculum-options">{#each curricula as course}<label><Checkbox checked={bulkCurricula.includes(course)} onCheckedChange={value=>bulkCurricula=toggleList(bulkCurricula,course,value===true)}/>{course}</label>{/each}</div><p class="bulk-note">{curriculaMode==='append'?'選択したカリキュラムを追加します。未選択なら変更しません。':'既存の担当カリキュラムを置き換えます。未選択ならすべて解除します。'}</p>{/if}</div>{/if}</Dialog.Body><Dialog.Footer><Button variant="outline" onclick={()=>bulkOpen=false}>キャンセル</Button><Button onclick={applyBulk}>{selectedTeachers.length}人に適用</Button></Dialog.Footer></Dialog.Content></Dialog.Root>

<style>
.email-indicator{display:inline-flex;align-items:center;color:var(--muted-foreground);flex-shrink:0}
.slack-requests{display:grid;gap:.5rem;margin-bottom:1rem}.slack-requests>div{display:flex;align-items:center;gap:.5rem;padding:.65rem .75rem;border:1px solid var(--border);border-radius:.75rem}.slack-requests>div>div{display:grid;flex:1}.slack-requests span{color:var(--muted-foreground);font-size:.8rem}
.teacher-toolbar{display:flex;align-items:center;gap:.75rem;margin-bottom:1rem;flex-wrap:wrap}.teacher-add{margin:0;display:flex;align-items:center;gap:.5rem;max-width:28rem;min-width:14rem;flex:1}.teacher-toolbar :global([data-slot="input"]),.teacher-toolbar :global([data-slot="button"]),.teacher-toolbar :global([data-slot="select-trigger"]){height:2.25rem;min-height:2.25rem;box-sizing:border-box;margin-block:0}.teacher-list{display:grid;gap:.5rem}.teacher-row{border:1px solid var(--border);border-radius:.85rem;overflow:hidden;background:var(--background)}.teacher-identity{display:flex;align-items:center;gap:.75rem;padding:.75rem 1rem}.avatar{display:grid;place-items:center;flex-shrink:0;width:2.5rem;height:2.5rem;border-radius:50%;background:color-mix(in oklch,var(--primary) 12%,var(--background));color:var(--primary);font-weight:700}.avatar img{width:100%;height:100%;object-fit:cover;border-radius:inherit}.teacher-info{display:grid;gap:.25rem;flex:1;min-width:0}.teacher-name{display:flex;align-items:center;gap:.5rem;flex-wrap:wrap}.teacher-name strong{font-size:1rem;overflow-wrap:anywhere}.role-badge{font-size:.75rem;background:var(--muted);border-radius:.25rem;padding:.1rem .4rem;color:var(--muted-foreground)}.teacher-filter{display:flex;align-items:center;gap:.75rem;min-width:0}.teacher-filter>span{white-space:nowrap;color:var(--muted-foreground);font-size:.875rem}.teacher-rooms{display:flex;flex-wrap:wrap;gap:.35rem;margin-top:.25rem;font-size:.875rem}.detail-chip{padding:.2rem .5rem;background:var(--muted);border-radius:.35rem}.detail-chip.current-room{background:color-mix(in oklch,var(--primary) 10%,var(--background));color:var(--primary)}.unassigned{font-size:.875rem;color:var(--muted-foreground)}.slack-indicator{display:inline-flex;flex-shrink:0}.teacher-slack{display:grid;gap:.75rem;border-top:1px solid var(--border);margin-top:1.25rem;padding-top:1rem;font-size:.875rem}.slack-unlink-note{margin:0;color:var(--muted-foreground)}.slack-label{font-weight:600}.slack-account{display:flex;align-items:center;flex:1;gap:.75rem;min-width:0;flex-wrap:wrap}.connected{color:var(--primary);font-weight:600}.slack-account-name{flex:1;min-width:0;overflow-wrap:anywhere}.slack-email{display:block;color:var(--muted-foreground);font-size:.8rem}.slack-error{display:flex;align-items:center;justify-content:space-between;gap:.75rem;flex-wrap:wrap;margin-bottom:1rem;font-size:.875rem}.teacher-empty{display:grid;justify-items:center;padding:3rem 1rem;gap:.75rem;text-align:center;color:var(--muted-foreground)}.teacher-empty p{margin:0}
.teacher-form{display:grid;grid-template-columns:1fr 1fr;gap:.75rem}.teacher-form label{display:grid;gap:.35rem}.curriculum-field,.bulk-section{display:grid;gap:.6rem;margin-top:1.1rem}.curriculum-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.5rem}.curriculum-options label{display:flex;align-items:center;gap:.5rem;padding:.55rem;border:1px solid var(--border);border-radius:.6rem}.bulk-section{padding-bottom:1rem;border-bottom:1px solid var(--border)}.bulk-section:last-child{border-bottom:0}.bulk-enable{display:flex;align-items:center;gap:.5rem}.bulk-note{margin:0;color:var(--muted-foreground);font-size:.8rem}.quick-actions{display:flex;gap:.25rem}@media(max-width:640px){.teacher-form,.curriculum-options{grid-template-columns:1fr}.teacher-identity{padding:1rem .75rem;gap:.5rem}.slack-account{flex-basis:100%}.teacher-toolbar{align-items:stretch;flex-direction:column}.teacher-add{max-width:none}}
</style>
